import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';

import { Job } from 'src/app/landing/models/job';
import { JobService } from 'src/app/service/job/job.service';
import { SharedModule } from 'src/app/shared/shared.module';

@Component({
  selector: 'app-all-jobs',
  templateUrl: './all-jobs.component.html',
  styleUrls: ['./all-jobs.component.css'],
  standalone: true,
  imports: [CommonModule, RouterModule, SharedModule]
})
export class AllJobsComponent implements OnInit {

  allJobs: Job[] = [];

  constructor(private jobService: JobService) {}

  ngOnInit(): void {
    this.getAllJobs();
  }

  getAllJobs(): void {
    this.jobService.getAllJobs().subscribe(res => {
      this.allJobs = res;
    });
  }
}
<div class="page">
<app-header variant="guest"></app-header>

<section class="section-pad">
  <div class="wrap">
    <div class="section-head">
      <h2>{{allJobs.length}} open roles</h2>
      <input type="text" placeholder="Search by keyword" style="padding:10px 14px;border:1px solid var(--line);border-radius:8px;width:280px;">
    </div>
    <div class="browse-grid">
      <div class="filters">
        <h4>Filters</h4>
        <div class="filter-group"><span class="lbl">Location</span>
          <select><option>Any location</option><option>Kochi, IN</option><option>Remote</option><option>Bengaluru</option></select>
        </div>
        <div class="filter-group"><span class="lbl">Experience</span>
          <select><option>Any level</option><option>0&ndash;2 years</option><option>3&ndash;5 years</option><option>5+ years</option></select>
        </div>
        <div class="filter-group"><span class="lbl">Skills</span>
          <span class="chip-choice selected">Java</span><span class="chip-choice">React</span>
          <span class="chip-choice">SQL</span><span class="chip-choice">AWS</span>
        </div>
        <button class="btn btn-primary btn-block">Apply filters</button>
      </div>
      <div class="table-wrap">
        <table>
          <thead><tr><th>Role</th><th>Company</th><th>Location</th><th>Salary</th><th>Status</th><th></th></tr></thead>
          <tbody>
            <tr *ngFor="let job of allJobs">
              <td>{{job.jobTitle}}</td>
              <td>{{job.companyName}}</td>
              <td>{{job.location}}</td>
              <td>&#8377;{{job.salary}}</td>
              <td><span class="chip" [ngClass]="job.active ? 'chip-open' : 'chip-closed'">{{ job.active ? 'Open' : 'Closed' }}</span></td>
              <td class="actions"><a [routerLink]="['/job/view-job', job.jobId]">View</a></td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </div>
</section>

<app-footer></app-footer>
</div>
